export function ArticleElement({
  title = "{{title}}",
  excerpt = "{{excerpt}}",
  author = "{{author}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const wrap = variant === "card"
    ? { border: "1.5px solid #24143022", boxShadow: "0 10px 24px rgba(36,20,48,.08)" }
    : { padding: 0 };
  return (
    <article style={{ width: 360, boxSizing: "border-box", font: "16px/1.55 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "22px 24px", borderRadius: 12, ...wrap }}>
      <p style={{ margin: "0 0 6px", fontSize: 11, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: accent }}>Article</p>
      <h2 style={{ margin: "0 0 10px", fontSize: 22, fontWeight: 700 }}>{title}</h2>
      <p style={{ margin: "0 0 14px", color: "#241430cc" }}>{excerpt}</p>
      <footer style={{ margin: 0, fontSize: 13, color: "#241430aa", borderTop: "1px solid #24143018", paddingTop: 12 }}>
        By {author} · self-contained, syndicatable on its own
      </footer>
    </article>
  );
}
